/**
 * Per-country prices for /pricing. The numbers come from the approved
 * client price guide (docs/pricing-source/client_pricing.html), generated by
 * docs/pricing-source/pricing.py + build_client_pricing.py.
 */
import data from "@/data/pricing.json";

export type Market = {
  /** Local freelancer range for a normal site. */
  free: [number, number];
  agency?: [number, number];
  diy?: string;
  /** What upkeep typically costs locally, as a sentence fragment. */
  care?: string;
};

/** Price groups by kind of business (docs/pricing-source/sector_prices.py). */
export const PRICE_KEYS = ["beauty", "food", "bar", "shop"] as const;
export type PriceKey = (typeof PRICE_KEYS)[number];

export const PRICE_LABEL: Record<PriceKey, string> = {
  beauty: "Barbers and salons",
  food: "Restaurants and takeaway",
  bar: "Bars and cafés",
  shop: "Online shop"
};

export type CountryPrice = {
  name: string;
  /** Currency format, "{}" is replaced by the amount, e.g. "€{}" or "{} zł". */
  fmt: string;
  /** The restaurant "from" price: the headline website price. */
  site: number;
  /** The online shop range (same as sectors.shop). */
  shop: [number, number];
  /** One-off price range for each kind of business. */
  sectors: Record<PriceKey, [number, number]>;
  /** Essential, Care, Growth (per month). */
  care: [number, number, number];
  market: Market | null;
};

export const PRICES = data as unknown as Record<string, CountryPrice>;

export const DEFAULT_COUNTRY = "de";

/** Last day a quote from this guide is honoured. */
export const VALID_UNTIL = "31 March 2027";

/** Country codes sorted by country name, for the picker. */
export const COUNTRY_CODES = Object.keys(PRICES).sort((a, b) =>
  PRICES[a].name.localeCompare(PRICES[b].name, "en")
);

export function isCountry(code: unknown): code is string {
  return typeof code === "string" && Object.prototype.hasOwnProperty.call(PRICES, code.toLowerCase());
}

export function money(c: CountryPrice, n: number) {
  const sep = c.fmt.includes("FCFA") ? " " : ",";
  return c.fmt.replace("{}", Math.round(n).toLocaleString("en-US").replace(/,/g, sep));
}

export function range(c: CountryPrice, a: number, b: number) {
  return `${money(c, a)} - ${money(c, b)}`;
}

/** Languages whose speakers mostly live in one of the priced countries. */
const LANGUAGE_COUNTRY: Record<string, string> = {
  de: "de", fr: "fr", es: "es", it: "it", pt: "pt", nl: "nl", pl: "pl", cs: "cz",
  hu: "hu", ro: "ro", el: "gr", sv: "se", da: "dk", nb: "no", no: "no", fi: "fi"
};

/**
 * Picks a priced country from a list of browser locales ("de-AT", "en-US", "fr").
 * Locales with a region win; a bare language falls back to its main country.
 */
export function countryFromLocales(locales: readonly string[]): string | undefined {
  for (const l of locales) {
    const region = l.split(/[-_]/)[1];
    if (region && isCountry(region)) return region.toLowerCase();
  }
  for (const l of locales) {
    const lang = l.split(/[-_]/)[0].toLowerCase();
    if (LANGUAGE_COUNTRY[lang] && isCountry(LANGUAGE_COUNTRY[lang])) return LANGUAGE_COUNTRY[lang];
  }
  return undefined;
}

/** Parses an Accept-Language header into locales, best first. */
export function parseAcceptLanguage(header: string | null | undefined): string[] {
  if (!header) return [];
  return header
    .split(",")
    .map((part) => {
      const [tag, ...params] = part.trim().split(";");
      const q = params.find((p) => p.trim().startsWith("q="));
      return { tag: tag.trim(), q: q ? Number(q.trim().slice(2)) || 0 : 1 };
    })
    .filter((x) => x.tag && x.tag !== "*")
    .sort((a, b) => b.q - a.q)
    .map((x) => x.tag);
}

/**
 * The country to show first: an explicit ?country=, then where the visitor
 * is (Vercel's geo header), then their browser languages, then Germany.
 */
export function pickCountry(opts: {
  query?: string | string[];
  ipCountry?: string | null;
  acceptLanguage?: string | null;
}): string {
  const q = Array.isArray(opts.query) ? opts.query[0] : opts.query;
  if (isCountry(q)) return q.toLowerCase();
  if (isCountry(opts.ipCountry)) return opts.ipCountry.toLowerCase();
  return countryFromLocales(parseAcceptLanguage(opts.acceptLanguage)) ?? DEFAULT_COUNTRY;
}

export type CompareRow = { label: string; from: number; to: number; me?: boolean };

/** Rows for the to-scale comparison chart, or null without market research. */
export function compareRows(c: CountryPrice): { rows: CompareRow[]; max: number; belowMiddle: boolean } | null {
  const m = c.market;
  if (!m) return null;
  const rows: CompareRow[] = [
    { label: "rira.build", from: c.site, to: c.site, me: true },
    { label: "Local freelancers", from: m.free[0], to: m.free[1] }
  ];
  if (m.agency) rows.push({ label: "Agencies", from: m.agency[0], to: m.agency[1] });
  const max = Math.max(...rows.map((r) => r.to)) * 1.05;
  return { rows, max, belowMiddle: c.site < (m.free[0] + m.free[1]) / 2 };
}
